    divider_row = None
    divider_col = None
    divider_color = None

    for i in range(h):
        row_vals = [grid[i][j] for j in range(w)]
        if len(set(row_vals)) == 1 and row_vals[0] != bg:
            divider_row = i
            divider_color = row_vals[0]
            break

    if divider_row is None:
        for j in range(w):
            col_vals = [grid[i][j] for i in range(h)]
            if len(set(col_vals)) == 1 and col_vals[0] != bg:
                divider_col = j
                divider_color = col_vals[0]
                break

    if divider_row is not None:
        # Horizontal divider at row
        # Find intruder color (not bg, not divider_color)
        intruder_color = None
        for i in range(h):
            for j in range(w):
                if grid[i][j] != bg and grid[i][j] != divider_color:
                    intruder_color = grid[i][j]
                    break
            if intruder_color:
                break

        # Move ALL intruder cells to (divider_row + 1, same_col)
        for i in range(h):
            for j in range(w):
                if grid[i][j] == intruder_color:
                    out[divider_row + 1][j] = intruder_color
                else:
                    out[i][j] = bg

        # Fill divider_row + 2 with 8s
        if divider_row + 2 < h:
            for j in range(w):
                out[divider_row + 2][j] = 8

        return out

    elif divider_col is not None:
        # Vertical divider
        # Find intruder color
        intruder_color = None
        for i in range(h):
            for j in range(w):
                if grid[i][j] != bg and grid[i][j] != divider_color:
                    intruder_color = grid[i][j]
                    break
            if intruder_color:
