        # Fill divider_col - 1 with 8s
        if divider_col - 1 >= 0:
            for i in range(h):
                out[i][divider_col - 1] = 8

            # Shift intrusers left (to divider_col - 2)
            for i in range(h):
                for j in range(w):
                    if grid[i][j] == intruder_color:
                        out[i][divider_col - 2] = intruder_color
                    else:
                        out[i][j] = bg

            return out

    return grid

